import * as THREE from 'three';

export const ART_THICKNESS = 0.06; // depth of each artwork box
export const GAP = 0.8; // required gap between artworks and margin at wall ends
export const EYE_LEVEL = 1.6; // y coordinate of artwork centers

/**
 * Wall descriptors in hang order. Each wall is parametrized by a single
 * axis coordinate `t` running left-to-right along the wall, with the
 * usable interval [-(len/2 - GAP), +(len/2 - GAP)].
 */
function wallConfigs(room) {
  const { w, d } = room;
  return [
    { name: 'north', axis: 'x', plane: -d / 2, len: w }, // z = -d/2, faces +z
    { name: 'east', axis: 'z', plane: w / 2, len: d }, // x = +w/2, faces -x
    { name: 'south', axis: 'x', plane: d / 2, len: w }, // z = +d/2, faces -z
    { name: 'west', axis: 'z', plane: -w / 2, len: d }, // x = -w/2, faces +x
  ];
}

function centerFor(wall, t, room) {
  const { w, d } = room;
  switch (wall.name) {
    case 'north':
      return new THREE.Vector3(t, EYE_LEVEL, -d / 2 + ART_THICKNESS / 2);
    case 'south':
      return new THREE.Vector3(t, EYE_LEVEL, d / 2 - ART_THICKNESS / 2);
    case 'east':
      return new THREE.Vector3(w / 2 - ART_THICKNESS / 2, EYE_LEVEL, t);
    case 'west':
      return new THREE.Vector3(-w / 2 + ART_THICKNESS / 2, EYE_LEVEL, t);
    default:
      throw new Error(`unknown wall ${wall.name}`);
  }
}

function rotationFor(wall) {
  // Artwork front (local +z) must point into the room.
  if (wall.name === 'east') return new THREE.Euler(0, -Math.PI / 2, 0);
  if (wall.name === 'west') return new THREE.Euler(0, Math.PI / 2, 0);
  return new THREE.Euler(0, 0, 0);
}

/**
 * Builds a THREE.Group containing the floor, four walls, and every artwork
 * hung according to the auto-hanging algorithm:
 *   - walls are filled in order north, east, south, west
 *   - within a wall artworks run left to right with GAP spacing
 *   - GAP margin is kept at both ends of every wall
 *   - artwork centers sit at EYE_LEVEL
 * Throws if an artwork is wider than any wall or the room runs out of space.
 */
export function buildGallery({ room = { w: 20, d: 12, h: 4 }, artworks = [] } = {}) {
  if (!room || !(room.w > 0) || !(room.d > 0) || !(room.h > 0)) {
    throw new Error('room must have positive w, d and h');
  }

  const group = new THREE.Group();
  group.name = 'gallery';

  const floorMat = new THREE.MeshBasicMaterial({ color: 0x887755 });
  const wallMat = new THREE.MeshBasicMaterial({ color: 0xf5f5f0 });
  const artMat = new THREE.MeshBasicMaterial({ color: 0x3344aa });

  // Floor
  const floor = new THREE.Mesh(new THREE.BoxGeometry(room.w, 0.1, room.d), floorMat);
  floor.name = 'floor';
  floor.position.y = -0.05;
  group.add(floor);

  // Four walls (thin boxes lying on the room boundary planes)
  for (const wall of wallConfigs(room)) {
    const alongX = wall.axis === 'x';
    const geo = new THREE.BoxGeometry(
      alongX ? room.w : 0.1,
      room.h,
      alongX ? 0.1 : room.d
    );
    const mesh = new THREE.Mesh(geo, wallMat);
    mesh.name = `wall-${wall.name}`;
    mesh.position.set(
      wall.name === 'east' ? room.w / 2 + 0.05 : wall.name === 'west' ? -room.w / 2 - 0.05 : 0,
      room.h / 2,
      wall.name === 'north' ? -room.d / 2 - 0.05 : wall.name === 'south' ? room.d / 2 + 0.05 : 0
    );
    group.add(mesh);
  }

  // Hang the artworks
  let wi = 0;
  let cursor = null; // next free t on current wall
  let wall = null;

  for (const spec of artworks) {
    if (!(spec.w > 0) || !(spec.h > 0)) {
      throw new Error(`artwork ${spec.id} must have positive w and h`);
    }
    if (spec.w > room.w - 2 * GAP && spec.w > room.d - 2 * GAP) {
      throw new Error(
        `artwork ${spec.id} (w=${spec.w}) is wider than any wall allows`
      );
    }

    // Advance to the first wall where this piece fits.
    while (true) {
      if (wall === null || cursor === null) {
        if (wi >= wallConfigs(room).length) {
          throw new Error(`no wall space left for artwork ${spec.id}`);
        }
        wall = wallConfigs(room)[wi++];
        cursor = -(wall.len / 2 - GAP); // left margin
      }
      const end = cursor + spec.w;
      if (end <= wall.len / 2 - GAP + 1e-9) break; // fits with right margin
      wall = null; // try next wall
      cursor = null;
    }

    const tCenter = cursor + spec.w / 2;
    const center = centerFor(wall, tCenter, room);

    const mesh = new THREE.Mesh(
      new THREE.BoxGeometry(spec.w, spec.h, ART_THICKNESS),
      artMat.clone()
    );
    mesh.name = `art-${spec.id}`;
    mesh.userData = { id: spec.id, wall: wall.name, width: spec.w, height: spec.h };
    mesh.position.copy(center);
    mesh.rotation.copy(rotationFor(wall));
    group.add(mesh);

    cursor += spec.w + GAP; // gap before the next piece
  }

  return group;
}

/**
 * Returns [{ id, wall, center }] for every artwork mesh in the group,
 * in hanging order.
 */
export function placements(g) {
  const out = [];
  g.traverse((obj) => {
    if (obj.isMesh && obj.userData && obj.userData.id !== undefined) {
      out.push({
        id: obj.userData.id,
        wall: obj.userData.wall,
        center: obj.position.clone(),
        width: obj.userData.width,
        height: obj.userData.height,
      });
    }
  });
  return out;
}

