import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildGallery, placements, ART_THICKNESS, GAP } from '../src/gallery.js';

const ROOM = { w: 20, d: 12, h: 4 };

// 7 mixed-size fixtures
const ARTWORKS = [
  { id: 'a1', w: 6, h: 2 },
  { id: 'a2', w: 5, h: 3 },
  { id: 'a3', w: 4, h: 2 },
  { id: 'a4', w: 7, h: 2.5 },
  { id: 'a5', w: 3, h: 2 },
  { id: 'a6', w: 4, h: 3 },
  { id: 'a7', w: 2, h: 1 },
];

function build() {
  return buildGallery({ room: ROOM, artworks: ARTWORKS });
}

// Horizontal interval of an artwork projected onto its wall's axis.
function interval(p) {
  const half = p.wall === 'north' || p.wall === 'south' ? p.width / 2 : p.height / 2;
  const t = p.wall === 'north' || p.wall === 'south' ? p.center.x : p.center.z;
  return [t - half, t + half];
}

describe('gallery auto-hanging', () => {
  it('hangs every artwork at eye level y = 1.6', () => {
    const ps = placements(build());
    expect(ps).toHaveLength(ARTWORKS.length);
    for (const p of ps) {
      expect(p.center.y).toBeCloseTo(1.6, 9);
    }
  });

  it('places every artwork back face exactly on its wall plane', () => {
    const ps = placements(build());
    for (const p of ps) {
      switch (p.wall) {
        case 'north':
          expect(p.center.z - ART_THICKNESS / 2).toBeCloseTo(-ROOM.d / 2, 6);
          break;
        case 'south':
          expect(p.center.z + ART_THICKNESS / 2).toBeCloseTo(ROOM.d / 2, 6);
          break;
        case 'east':
          expect(p.center.x + ART_THICKNESS / 2).toBeCloseTo(ROOM.w / 2, 6);
          break;
        case 'west':
          expect(p.center.x - ART_THICKNESS / 2).toBeCloseTo(-ROOM.w / 2, 6);
          break;
        default:
          throw new Error(`unexpected wall ${p.wall}`);
      }
    }
  });

  it('has no overlaps on the same wall and gaps of at least 0.8', () => {
    const byWall = {};
    for (const p of placements(build())) (byWall[p.wall] ??= []).push(p);

    for (const [wall, ps] of Object.entries(byWall)) {
      const ivs = ps.map(interval).sort((a, b) => a[0] - b[0]);
      for (let i = 1; i < ivs.length; i++) {
        // no overlap
        expect(ivs[i][0]).toBeGreaterThanOrEqual(ivs[i - 1][1]);
        // gap of at least GAP between consecutive pieces
        expect(ivs[i][0] - ivs[i - 1][1]).toBeGreaterThanOrEqual(GAP - 1e-6);
      }
    }
  });

  it('produces the hand-computed wall assignment', () => {
    // Hand computation with room w=20 d=12, margins/gaps of 0.8:
    //   north (usable x in [-9.2, 9.2]):
    //     a1(6): [-9.2,-3.2] c=-6.2 ; a2(5): [-2.4,2.6] c=0.1 ;
    //     a3(4): [3.4,7.4] c=5.4 ; a4(7) would end at 15.2 > 9.2 -> next wall
    //   east (usable z in [-5.2, 5.2]):
    //     a4(7): [-5.2,1.8] c=-1.7 ; a5(3) would end at 5.6 > 5.2 -> next wall
    //   south (usable x in [-9.2, 9.2]):
    //     a5(3): [-9.2,-6.2] c=-7.6 ; a6(4): [-5.4,-1.4] c=-3.4 ;
    //     a7(2): [-0.6,1.4] c=0.4
    //   west: unused
    const expected = {
      a1: { wall: 'north', center: new THREE.Vector3(-6.2, 1.6, -ROOM.d / 2 + ART_THICKNESS / 2) },
      a2: { wall: 'north', center: new THREE.Vector3(0.1, 1.6, -ROOM.d / 2 + ART_THICKNESS / 2) },
      a3: { wall: 'north', center: new THREE.Vector3(5.4, 1.6, -ROOM.d / 2 + ART_THICKNESS / 2) },
      a4: { wall: 'east', center: new THREE.Vector3(ROOM.w / 2 - ART_THICKNESS / 2, 1.6, -1.7) },
      a5: { wall: 'south', center: new THREE.Vector3(-7.6, 1.6, ROOM.d / 2 - ART_THICKNESS / 2) },
      a6: { wall: 'south', center: new THREE.Vector3(-3.4, 1.6, ROOM.d / 2 - ART_THICKNESS / 2) },
      a7: { wall: 'south', center: new THREE.Vector3(0.4, 1.6, ROOM.d / 2 - ART_THICKNESS / 2) },
    };

    const ps = placements(build());
    for (const art of ARTWORKS) {
      const p = ps.find((x) => x.id === art.id);
      const e = expected[art.id];
      expect(p.wall, `wall for ${art.id}`).toBe(e.wall);
      expect(p.center.x, `x for ${art.id}`).toBeCloseTo(e.center.x, 6);
      expect(p.center.y, `y for ${art.id}`).toBeCloseTo(e.center.y, 6);
      expect(p.center.z, `z for ${art.id}`).toBeCloseTo(e.center.z, 6);
    }
  });

  it('throws when an artwork is wider than any wall', () => {
    expect(() =>
      buildGallery({ room: ROOM, artworks: [{ id: 'big', w: 25, h: 2 }] })
    ).toThrow(/wider than any wall/);
  });

  it('builds the floor and four walls plus the artworks', () => {
    const g = build();
    const names = g.children.map((c) => c.name);
    expect(names).toContain('floor');
    for (const wall of ['north', 'east', 'south', 'west']) {
      expect(names).toContain(`wall-${wall}`);
    }
    expect(g.children.filter((c) => c.name.startsWith('art-'))).toHaveLength(7);
  });
});

